# LINEAGE (Seat R 76th, 2026-11-03): re-keyed copy of Seat W 17th's pushlock_w17_newbranch_v3.sh by READING it: only the seat token, the env-var prefix W17_ -> R76_, tool names, paths and the planted-control path changed; every gate is unchanged. Remaining mentions of W 17th are historical comments, listed in evidence/rekey_batch3.out.
# gate (overlap_gate.sh, Wednesday's condition on the KS-1458 baseline grant: re-run the intersection immediately before the push) inside precheck().
# v2 (2026-10-28 08:50Z): the develop gate is Wednesday's no-overlap rule (develop_gate.sh), not containment. Everything else as v1.
# and treated every non-zero as "state changed" (exit 5), which would drop a queued seat after an hour on one network blip. Now: rc 2 while queued is counted and tolerated
# (X8_NETMAX in a row, default 5, then exit 6); rc 2 before joining or under the lock stops with exit 6 and nothing pushed. Exit codes: 5 refused, 6 could not say.
# ONE push of a NEW branch (origin must not hold it yet). bash 3.2 safe (macOS).
# The existing-branch parts (OLD_ORIGIN_HEAD, the ACCEPT=RULE overlap rule) are removed and the precheck is changed for a first push. SEATNAME, the last argument, is the only seat token.
# Order: precheck -> join the first-come queue -> wait my turn -> take the lock by my OWN mkdir -> gates -> push -> ls-remote -> release -> leave.
# Every knob is a REQUIRED argument; nothing is inherited from a predecessor's constants.
# X7 (round 2 after gate 227's NO GO, Wednesday's BRIEF 08:21:02Z, ANSWER 08:30:32Z): an exit code is not a decision, and decide and the PR-line tool are pinned by sha (finding 2); stderr kept out of the read-back (8); the PR line is written from the push result (11); a heartbeat past MY TURN (17); the seat name is an argument (18).
#   pushlock_x8_newbranch_v3.sh WORKTREE BRANCH EXPECT_HEAD BASE_DEVELOP OUTDIR LOCKDIR QUEUEDIR QUEUETOOL MAXTURN MAXPOLL real|dryrun|gatetest KEYFILE PATHSFILE RECORD CELLSFILE SEATNAME
# X7: SEATNAME reads like 'Seat X 8th'; it goes on the ticket and the lock holder (gate finding 18).
# X7: RECORD = the seat's pre-run record.json (prerun_x5.py run); CELLSFILE = the one-line expected run_shell_suites cell count next to the tool. A missing record falls back to the hook.
# X7: at the turn, under the lock, prerun_decide_x8.py picks the path: QUALIFIES -> git push --no-verify of the explicit sha; FALL BACK (too old, other sha, count differs, anything not a FAILED
# X7: pre-run) -> today's push, the hook under the lock, place kept; FAILED pre-run -> exit 5 and the seat leaves the queue. NEW BRANCHES ONLY, as in v3.
# real     : everything, including the push.
# dryrun   : queue -> lock -> hold 2 s -> release, against the scratch LOCKDIR/QUEUEDIR the caller passes. No gates, no push.
# gatetest : the prechecks and the gates under the lock, then stop BEFORE the push (the hook-running gate is skipped: it only means something
#            against the real lock).
# Develop gate: origin develop must be CONTAINED in EXPECT_HEAD (it is exactly BASE_DEVELOP while nothing has merged); if develop moved past what
# the branch was built on, nothing is pushed and the driver exits 5 (the caller then asks the coordinator; a merge-in is not this tool's job).
# Ownership of the lock comes ONLY from this script's own successful mkdir (ACQ=1). A [ -d ] test is never used to decide ownership; it is used once,
# after my own rmdir, to assert the post-state of the release.
set -u
[ $# -eq 16 ] || { echo "usage: pushlock_x8_newbranch_v3.sh WORKTREE BRANCH EXPECT_HEAD BASE_DEVELOP OUTDIR LOCKDIR QUEUEDIR QUEUETOOL MAXTURN MAXPOLL real|dryrun|gatetest KEYFILE PATHSFILE RECORD CELLSFILE SEATNAME" >&2; exit 64; }  # X7: 13 -> 16 (RECORD, CELLSFILE, SEATNAME)
WT="$1"; BR="$2"; EXPECT="$3"; BASED="$4"; OUT="$5"; LOCK="$6"; QDIR="$7"; QTOOL="$8"; MAXTURN="$9"; MAXPOLL="${10}"; MODE="${11}"; KEY="${12}"; OVL_PATHS="${13}"; RECORD="${14}"; CELLS="${15}"; SEAT="${16}"
case "$SEAT" in "Seat "[A-Z]*" "[0-9]*) ;; *) echo "SEATNAME must read like 'Seat X 8th' (got [$SEAT])" >&2; exit 64 ;; esac
case "$0" in /*) ;; *) echo "invoke the driver by its ABSOLUTE path (no cd)" >&2; exit 64 ;; esac
GATE="$(dirname "$0")/develop_gate.sh"; [ -f "$GATE" ] || { echo "develop_gate.sh not found next to the driver" >&2; exit 64; }
case "$MODE" in real|dryrun|gatetest) ;; *) echo "MODE must be real, dryrun or gatetest" >&2; exit 64 ;; esac
case "$EXPECT" in [0-9a-f]*) [ ${#EXPECT} -eq 40 ] || { echo "EXPECT_HEAD must be 40 hex" >&2; exit 64; } ;; *) echo "EXPECT_HEAD must be 40 hex" >&2; exit 64 ;; esac
case "$BASED" in [0-9a-f]*) [ ${#BASED} -eq 40 ] || { echo "BASE_DEVELOP must be 40 hex" >&2; exit 64; } ;; *) echo "BASE_DEVELOP must be 40 hex" >&2; exit 64 ;; esac
[ -f "$KEY" ] || { echo "KEYFILE $KEY does not exist" >&2; exit 64; }
OVL="$(dirname "$0")/overlap_gate.sh"; [ -f "$OVL" ] || { echo "overlap_gate.sh not found next to the driver" >&2; exit 64; }
[ -s "$OVL_PATHS" ] || { echo "PATHSFILE $OVL_PATHS is missing or empty" >&2; exit 64; }
# X7: the three helpers sit next to the driver, like the two gates.
DECIDE="$(dirname "$0")/prerun_decide_x8.py"; [ -f "$DECIDE" ] || { echo "prerun_decide_x8.py not found next to the driver" >&2; exit 64; }
BOUND="$(dirname "$0")/bound_x8.py"; [ -f "$BOUND" ] || { echo "bound_x8.py not found next to the driver" >&2; exit 64; }
SSHW="$(dirname "$0")/sshv_x8.sh"; [ -f "$SSHW" ] || { echo "sshv_x8.sh not found next to the driver" >&2; exit 64; }
PRLINE="$(dirname "$0")/prerun_prline_x8.py"; [ -f "$PRLINE" ] || { echo "prerun_prline_x8.py not found next to the driver" >&2; exit 64; }
# X7 (finding 2): [ -f ] is not enough: an emptied or swapped decide must not answer. Stamped by rekey_push_x8.py; a differing file takes the hook path.
DECIDE_PIN="fc335d76cf4ba6389885c9033ebe7047a036918a22f7e703d26af7bb4fc20894"
PRLINE_PIN="71ba3d8de71c34ad3f75b724a61da0482d16ca547dbfc4291875776452bc9f22"
sha_of() { shasum -a 256 "$1" 2>/dev/null | awk '{print $1}'; }
# X7: knobs. The defaults are the production values; the env names are read for the rehearsal only (like X8_NETMAX); each must be a whole number >= 1.
knob() { eval "kv=\${$1:-$2}"; case "$kv" in ''|*[!0-9]*) echo "$1 must be a whole number" >&2; return 1 ;; esac; [ "$kv" -ge 1 ] || { echo "$1 must be at least 1" >&2; return 1; }; echo "$kv"; }
PRECHK_EVERY=$(knob X8_PRECHECK_EVERY 100) || exit 64      # polls between the periodic prechecks while queued: 100 x 3 s = ~5 min (v3: 20 = ~1 min; X 5th's design point FOR THE DESIGN (1))
HB_EVERY=$(knob X8_HEARTBEAT_EVERY 20) || exit 64          # polls between status.txt heartbeat lines: 20 x 3 s = ~1 min
NET_BOUND=$(knob X8_NET_BOUND 120) || exit 64              # hard wall-clock bound, seconds, of EVERY git network call and of the overlap gate while waiting and under the lock
PUSH_BOUND=$(knob X8_PUSH_BOUND 240) || exit 64            # the --no-verify push (normally ~30 s): a hung one is killed, origin is read, up to 2 retries
HOOKPUSH_BOUND=$(knob X8_HOOKPUSH_BOUND 3000) || exit 64   # the fallback push that runs the hook (measured 1152 to 1262 s) plus the 30 min ssh keepalive allowance
RETRY_SLEEP=$(knob X8_RETRY_SLEEP 20) || exit 64
POLL_SLEEP=$(knob X8_POLL_SLEEP 3) || exit 64
LIVE_BOUND=$(knob X8_LIVE_BOUND 20) || exit 64          # X8 (gate 237 N4b): hard bound, seconds, of ONE live check (normally ~0.2 s); under the lock it is the only time N4b adds
export PUSH_QUEUE_DIR="$QDIR"
mkdir -p "$OUT" || exit 65
ST="$OUT/status.txt"; : > "$ST"
rm -f "$OUT/decision.json" "$OUT/pr_line.txt" "$OUT/push.rc" "$OUT/push.rc.all" "$OUT/push.path"   # X7 (finding 11): a reused OUTDIR must not answer for this run
say() { echo "$(date -u +%H:%M:%SZ) $*" >> "$ST"; }
export X8_SSHLOG="$OUT/ssh.log"   # X7: ssh -v with a UTC time on every line (sshv_x8.sh), so the next push death names its second
SSH="bash $SSHW -i $KEY -o IdentitiesOnly=yes -o StrictHostKeyChecking=accept-new -o ServerAliveInterval=15 -o ServerAliveCountMax=120"
# X7: EVERY git network call runs under a hard wall-clock bound (bound_x8.py kills the whole process group); rc 124 = the bound fired, which every caller already reads as a failure / "could not say".
gitnet_b() { local b="$1"; shift; python3 -I "$BOUND" "$b" env -u GIT_SSH_COMMAND git -C "$WT" -c core.sshCommand="$SSH" "$@"; }
gitnet() { gitnet_b "$NET_BOUND" "$@"; }
# X8 (gate 237 N4b): is a pre-run live in MY tree? Asked of the PINNED decide (`live`), under its own short bound. 0 = LIVE (PL_LAST names it), 1 = NONE, 2 = could not say.
# As for decide (finding 2), an exit code is not an answer: LIVE needs exit 0 AND the LIVE statement as the last line, NONE needs exit 1 AND the NONE statement; a crash prints neither.
prerun_live() {
  PLIVE="prerun_decide_x8.py is not the pinned file, so its live answer is not read"; PL_LAST=""
  [ "$(sha_of "$DECIDE")" = "$DECIDE_PIN" ] || return 2
  PLIVE=$(python3 -I "$BOUND" "$LIVE_BOUND" python3 -I "$DECIDE" live "$WT" 2> "$OUT/live.err"); vrc=$?; PL_LAST=$(printf '%s\n' "$PLIVE" | tail -1)
  case "$vrc|$PL_LAST" in "0|LIVE-CHECK LIVE "*) return 0 ;; esac
  case "$vrc|$PL_LAST" in "1|LIVE-CHECK NONE wt="*) return 1 ;; esac
  PLIVE="live check rc=$vrc: [$(printf '%s ' "$PLIVE" | head -c 160)] $(head -c 160 "$OUT/live.err" 2>/dev/null | tr '\n' ' ')"; return 2
}

ACQ=0; TICKET=""
# X7 (finding 17): status.txt keeps moving past MY TURN, through the gates and a hook of twenty minutes, so a quiet file means a stuck driver everywhere. It ends with the driver: a KILLed driver's heartbeat stops within one poll.
start_hb() { ( i=0; while kill -0 $$ 2>/dev/null; do sleep "$POLL_SLEEP"; i=$((i+1)); if [ $((i % HB_EVERY)) -eq 0 ]; then say "heartbeat: past MY TURN, $i polls, driver alive"; fi; done ) & }
release() {
  [ "$ACQ" -eq 1 ] || return 0
  rm -f "$LOCK/holder"; rm_rc=$?
  rmdir "$LOCK" 2> "$OUT/rmdir.err"; rd_rc=$?
  if [ "$rd_rc" -ne 0 ] || [ -d "$LOCK" ]; then
    say "LOUD STOP: lock release FAILED (rm rc=$rm_rc rmdir rc=$rd_rc dir-still-there=$([ -d "$LOCK" ] && echo YES || echo no)): $(cat "$OUT/rmdir.err")"
    exit 9
  fi
  say "released: rm_rc=$rm_rc rmdir_rc=$rd_rc; lock dir exists afterwards: no"
  ACQ=0
}
leave_queue() {
  [ -n "$TICKET" ] || return 0
  lv=$(bash "$QTOOL" leave "$TICKET" 2>&1); lrc=$?
  say "queue leave rc=$lrc: $lv"
  TICKET=""
  [ "$lrc" -eq 0 ] || exit 8
}
on_exit() { ec=$?; [ -f "$OUT/pr_line.txt" ] || printf 'NO PR LINE: this driver ended with exit %s and no push result. Read %s.\n' "$ec" "$ST" > "$OUT/pr_line.txt"; release; leave_queue; }   # X7 (finding 11): every path that wrote no line says so plainly
trap on_exit EXIT
trap 'exit 130' INT TERM HUP

# One precheck, used before joining the queue and again under the lock. Prints the reason on failure and returns 1; each check is its own step.
precheck() {
  tip=$(git -C "$WT" rev-parse "refs/heads/$BR" 2>&1)
  [ "$tip" = "$EXPECT" ] || { PWHY="local tip $tip != declared head $EXPECT"; return 1; }
  git -C "$WT" merge-base --is-ancestor "$BASED" "$EXPECT" || { PWHY="BASE_DEVELOP $BASED is not an ancestor of $EXPECT, so it is not the develop this branch was built on"; return 1; }
  # X8 (gate 237 N1, N4a): the exit code is read, so a status that cannot be read is NOT clean; --no-optional-locks, so a queued driver never takes index.lock under a pre-run's legs.
  st=$(git --no-optional-locks -C "$WT" status --porcelain 2> "$OUT/status.err"); src=$?
  PDIRT=""; [ "$src" -eq 0 ] || PDIRT="git status failed rc=$src, so the tree cannot be shown clean: $(head -c 200 "$OUT/status.err" | tr '\n' ' ')"
  [ -n "$PDIRT" ] || [ -z "$st" ] || PDIRT="worktree not clean: $(printf '%s\n' "$st" | head -3 | tr '\n' ';')"
  # X8 (gate 237 N4b): dirt while a pre-run is live in MY tree is not judged now (the pre-run reads its own tree; decide judges its record); every other check below still runs, and precheck
  # returns 3. With no live pre-run: refuse, as before. If whether one is live cannot be read: CANNOT SAY (2), as for a network read.
  if [ -n "$PDIRT" ]; then
    prerun_live; vr=$?
    [ "$vr" -ne 2 ] || { PWHY="CANNOT SAY: $PDIRT; and whether a pre-run is live in this tree could not be read: $PLIVE"; return 2; }
    [ "$vr" -eq 0 ] || { PWHY="$PDIRT"; return 1; }
    PDIRT="a pre-run is live in my tree ($PL_LAST), so the tree is not judged while it runs: $PDIRT"
  fi
  [ "$(git -C "$WT" config --get core.hooksPath)" = ".githooks" ] || { PWHY="core.hooksPath is not .githooks"; return 1; }
  [ -x "$WT/.githooks/pre-push" ] || { PWHY="$WT/.githooks/pre-push is not executable (git would skip it silently)"; return 1; }
  # A first push: origin must NOT hold this branch name (a merged PR's head can carry a Linear branch name; a push there is a refused non-fast-forward).
  # v3 (2026-10-30 04:2xZ): the ls-remote's own rc is read (v1/v2 piped it into awk, so a timeout read as "origin does not hold the branch").
  # precheck returns 0 = ok, 1 = refuse (state changed), 2 = CANNOT SAY (network or instrument error); callers treat 2 differently from 1.
  ob=$(gitnet ls-remote origin "refs/heads/$BR" 2> "$OUT/lsr_branch.err"); lrc=$?
  [ "$lrc" -eq 0 ] || { PWHY="CANNOT SAY: ls-remote of $BR failed rc=$lrc: $(head -c 200 "$OUT/lsr_branch.err" | tr '\n' ' ')"; return 2; }
  ob=$(printf '%s\n' "$ob" | awk '{print $1}')
  [ -z "$ob" ] || { PWHY="origin already holds $BR at [$ob]; this driver pushes a NEW branch only"; return 1; }
  # v2 (Wednesday's rule for a develop move, develop_gate.sh): fetch develop's objects (URL form, so FETCH_HEAD only and no tracking ref is written),
  # then judge by file overlap with the branch, the two Projects Documents docs aside. Sha equality / containment is NOT required.
  k=0; dev=""
  while [ "$k" -lt 3 ]; do
    gitnet fetch --quiet "$(git -C "$WT" config --get remote.origin.url)" refs/heads/develop > "$OUT/fetch.out" 2>&1 || { PWHY="CANNOT SAY: fetch of origin develop failed: $(head -c 200 "$OUT/fetch.out" | tr '\n' ' ')"; return 2; }
    dev=$(gitnet ls-remote origin refs/heads/develop 2> "$OUT/lsr_dev.err"); lrc=$?
    [ "$lrc" -eq 0 ] || { PWHY="CANNOT SAY: ls-remote develop failed rc=$lrc: $(head -c 200 "$OUT/lsr_dev.err" | tr '\n' ' ')"; return 2; }
    dev=$(printf '%s\n' "$dev" | awk '{print $1}')
    [ ${#dev} -eq 40 ] || { PWHY="CANNOT SAY: ls-remote develop returned [$dev]"; return 2; }
    git -C "$WT" cat-file -e "${dev}^{commit}" 2>/dev/null && break
    k=$((k+1)); sleep 2     # develop moved between the fetch and the ls-remote: fetch again
  done
  git -C "$WT" cat-file -e "${dev}^{commit}" 2>/dev/null || { PWHY="CANNOT SAY: origin develop $dev is still not in the object store after 3 fetches"; return 2; }
  # both gates exit 1 = refuse, 2 = cannot say (their own headers); keep that difference
  PNOTE=$(bash "$GATE" "$WT" "$BASED" "$EXPECT" "$dev"); grc=$?
  [ "$grc" -eq 0 ] || { [ "$grc" -eq 2 ] && PWHY="CANNOT SAY: develop gate rc=$grc: $PNOTE" || PWHY="develop gate rc=$grc: $PNOTE"; [ "$grc" -eq 2 ] && return 2; return 1; }
  # No open PR may touch the listed paths (Wednesday: STOP and mail, do not merge through).
  POVL=$(python3 -I "$BOUND" "$NET_BOUND" bash "$OVL" "$OVL_PATHS"); orc=$?
  [ "$orc" -ne 124 ] || { orc=2; POVL="the overlap gate (gh, the GitHub API) hung past ${NET_BOUND} s and was killed"; }   # X7: a hung gate is "cannot say", like a hung ssh
  [ "$orc" -eq 0 ] || { [ "$orc" -eq 2 ] && PWHY="CANNOT SAY: overlap gate rc=$orc: $POVL" || PWHY="overlap gate rc=$orc: $POVL"; [ "$orc" -eq 2 ] && return 2; return 1; }
  PNOTE="$PNOTE; $POVL"
  PDEV="$dev"; [ -z "$PDIRT" ] || { PWHY="$PDIRT"; return 3; }   # X8 (gate 237 N4b): all else passed; the only thing not judged is a live pre-run's tree
  PWHY=""; return 0
}

say "driver start pid=$$ mode=$MODE wt=$WT branch=$BR expect=$EXPECT base=$BASED lock=$LOCK queue=$QDIR"
precheck; prc=$?
[ "$prc" -eq 0 ] || { say "PRECHECK FAIL (before joining the queue), rc=$prc: $PWHY"; [ "$prc" -eq 2 ] && exit 6; exit 5; }
say "precheck ok: tip=$EXPECT, built on $BASED, clean, hooks armed, origin does not hold $BR, develop $PDEV: $PNOTE"

# ---- 0. queue: join ONCE with MY pid (alive for the whole push), then wait for my turn --------------------------------------
if [ -n "${X8_ADOPT_PREFIX:-}" ]; then
  # ADOPT mode (Wednesday ruling 06:08Z, to keep a place across the 2 h task limit): do NOT join. The caller re-keys its OWN ticket to <prefix>-<this pid> with one mv;
  # this driver waits for that file and uses it. X8_ADOPT_PREFIX is the <epoch>.<nanos> join-time part of the ticket name (it is the queue order).
  case "$X8_ADOPT_PREFIX" in [0-9]*.[0-9]*) ;; *) say "X8_ADOPT_PREFIX must look like <epoch>.<nanos>"; exit 64 ;; esac
  AT="$QDIR/${X8_ADOPT_PREFIX}-$$"
  say "ADOPT mode: not joining; waiting up to ${X8_ADOPT_WAIT:-300} s for the ticket $AT to appear (the caller renames its own ticket to this name)"
  aw=0; while [ ! -f "$AT" ] && [ "$aw" -lt "${X8_ADOPT_WAIT:-300}" ]; do sleep 1; aw=$((aw+1)); done
  [ -f "$AT" ] || { say "adopt: the ticket never appeared after $aw s; nothing was joined"; exit 7; }
  TICKET="$AT"
  say "queue ADOPTED: $TICKET | queue now: $(bash "$QTOOL" list | tr '\n' ';')"
else
  TICKET=$(PUSH_QUEUE_PID=$$ bash "$QTOOL" join "$SEAT" 2> "$OUT/join.err"); jrc=$?
  if [ "$jrc" -ne 0 ] || [ -z "$TICKET" ]; then say "queue join FAILED rc=$jrc: $(cat "$OUT/join.err")"; TICKET=""; exit 7; fi
  say "queue joined: $TICKET | queue now: $(bash "$QTOOL" list | tr '\n' ';')"
fi
t=0; trc=1
# v3: a periodic check that CANNOT SAY (rc 2: network or instrument) does not cost me my place; NETMAX of them in a row do (exit 6). X8_NETMAX is read for the rehearsal only.
NETMAX="${X8_NETMAX:-5}"; case "$NETMAX" in ''|*[!0-9]*) echo "X8_NETMAX must be a number" >&2; exit 64 ;; esac
NETFAIL=0
while [ "$t" -lt "$MAXTURN" ]; do
  bash "$QTOOL" turn "$TICKET" 2> "$OUT/turn.err"; trc=$?
  [ "$trc" -eq 0 ] && break
  [ "$trc" -eq 1 ] || { say "queue turn ERROR rc=$trc: $(cat "$OUT/turn.err")"; exit 7; }
  t=$((t+1)); sleep "$POLL_SLEEP"
  # X7 (ADDENDUM 06:36:21Z, a queued driver's hung ssh): status.txt moves every HB_EVERY polls, so a quiet file means a stuck driver, never a patient one.
  if [ $((t % HB_EVERY)) -eq 0 ]; then say "heartbeat: poll $t, waited ${SECONDS}s, still queued"; fi
  # X7: every PRECHK_EVERY polls (default 100, ~5 min; v3 ~60 s): if develop moved past what I built on, there is no point holding a place I would have to give up at the lock.
  if [ $((t % PRECHK_EVERY)) -eq 0 ]; then
    precheck; prc=$?
    if [ "$prc" -eq 2 ]; then
      NETFAIL=$((NETFAIL+1))
      say "periodic check could not say (poll $t, $NETFAIL in a row, limit $NETMAX): $PWHY; staying in the queue"
      [ "$NETFAIL" -le "$NETMAX" ] || { say "more than $NETMAX periodic checks in a row could not say; leaving the queue, nothing pushed"; exit 6; }
    elif [ "$prc" -eq 3 ]; then
      say "periodic check (poll $t): $PWHY; staying in the queue, the place is kept"   # X8 (gate 237 N4b): not an exit, and not counted against NETMAX
    elif [ "$prc" -ne 0 ]; then
      say "develop/branch state changed while queued (poll $t): $PWHY; leaving the queue, nothing pushed"; exit 5
    else
      [ "$NETFAIL" -eq 0 ] || say "periodic check says again after $NETFAIL that could not"
      NETFAIL=0
      say "still queued at poll $t: $(bash "$QTOOL" list | tr '\n' ';')"
    fi
  fi
done
[ "$trc" -eq 0 ] || { say "gave up waiting for my turn after $t polls; leaving the queue"; exit 1; }
say "MY TURN after $t polls (turn rc 0)"
start_hb

# ---- 1. acquire: poll at 3 s, bounded; the flag is set INSIDE the loop on the mkdir that SUCCEEDED ----------------------------
# X8 (gate 237 N4b): a pre-run live in MY tree at my turn: wait for it to end, holding NO lock, inside the lock wait's own budget (MAXPOLL x 3 s from MY TURN), so the hook never
# starts beside it. A live check that cannot say ends the wait (as before round 3); the read just before decide, under the lock, is the last word.
T_TURN=$SECONDS; pw=0
while prerun_live; do
  [ $((SECONDS - T_TURN)) -lt $((MAXPOLL * 3)) ] || { say "the pre-run in my tree ($PL_LAST) outlived the lock wait's budget of $((MAXPOLL * 3)) s; no lock taken, nothing pushed"; break; }
  [ $((pw % HB_EVERY)) -eq 0 ] && say "MY TURN, but a pre-run is live in my tree ($PL_LAST): waiting for it to end, holding no lock ($((SECONDS - T_TURN)) s of $((MAXPOLL * 3)))"
  pw=$((pw+1)); sleep 3
done
[ "$pw" -eq 0 ] || say "waited $((SECONDS - T_TURN)) s at my turn for the pre-run in my tree; the live check now says: [$PL_LAST]"
i=$(( (SECONDS - T_TURN) / 3 ))
while [ "$i" -lt "$MAXPOLL" ]; do
  if mkdir "$LOCK" 2> "$OUT/mkdir.err"; then ACQ=1; break; fi
  if ! /usr/bin/grep -q 'File exists' "$OUT/mkdir.err"; then
    say "mkdir failed and it is NOT EEXIST (so not 'held by another seat'): $(cat "$OUT/mkdir.err")"; exit 2
  fi
  i=$((i+1)); sleep 3
done
[ "$ACQ" -eq 1 ] || { say "timed out after $i polls; lock never taken; holder at exit: $(cat "$LOCK/holder" 2>&1)"; exit 1; }
printf '%s | %s | %s | %s\n' "$SEAT" "$$" "$BR" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" > "$LOCK/holder"
say "ACQUIRED after $i polls; holder written: $(cat "$LOCK/holder")"

if [ "$MODE" = dryrun ]; then
  say "dryrun: gates and push skipped; holding 2 s"; sleep 2; exit 0
fi

# ---- 2. gates, with the lock held, each its own step --------------------------------------------------------------------------
n=0; seen=''
if [ "$MODE" = real ]; then
  while [ "$n" -lt 60 ]; do
    seen=$(pgrep -fl '^/bin/sh [.]githooks/pre-push origin git@github[.]com:'); [ -z "$seen" ] && break; n=$((n+1)); sleep 3
  done
  [ -z "$seen" ] || { say "GATE FAIL: a pre-push hook is still running with the lock mine: $seen"; exit 3; }
  say "gate ok: no pre-push hook running (waited $n polls)"
else
  say "gatetest: the hook-running gate is skipped; it only means something against the REAL lock"
fi
precheck; prc=$?
[ "$prc" -eq 0 ] || { say "GATE FAIL (under the lock), rc=$prc: $PWHY; nothing pushed"; [ "$prc" -eq 2 ] && exit 6; exit 5; }
say "gate ok: develop $PDEV ($PNOTE); origin does not hold $BR; worktree clean; hook armed"
# X8 (gate 237 N4b): one more read, just before decide. A pre-run started in my tree after my turn is refused here: nothing pushed, no hook beside it (a wait here would be a
# new wait under the lock). A read that cannot say goes on as before round 3: decide, then --no-verify only on its positive statement, else the hook.
prerun_live; ulr=$?
[ "$ulr" -ne 0 ] || { say "GATE FAIL (under the lock): a pre-run started in my tree after my turn ($PL_LAST); nothing pushed, no hook beside it, leaving the queue"; exit 5; }
[ "$ulr" -ne 2 ] || say "could not tell whether a pre-run is live in my tree ($PLIVE); going on as before round 3"
# X7 (Wednesday's gap 1 ruling, ANSWER 06:34:04Z): which push path does the pre-run record earn? Decided HERE, under the lock, after the develop and overlap gates.
#   exit 0  QUALIFIES -> --no-verify push of the explicit sha;  exit 10 FALL BACK -> today's push (the hook runs), place kept;  exit 5 FAILED pre-run -> refuse, leave the queue;
#   anything else is an instrument error: fall back and say so (a fallback never removes a guard). The tool also reads git itself: the pushed sha is not the record's claim.
# X7 (finding 2): an exit code is not a decision. --no-verify needs exit 0 AND the positive statement on decide's LAST stdout line AND the same decision in decision.json, from a decide whose sha matches the pin. Anything else, an exit 0 with no decision, an empty or truncated file, takes the hook path.
if [ "$(sha_of "$DECIDE")" = "$DECIDE_PIN" ]; then
  DEC=$(python3 -I "$BOUND" "$NET_BOUND" python3 -I "$DECIDE" decide "$RECORD" "$EXPECT" --branch "$BR" --worktree "$WT" --cells-file "$CELLS" --out "$OUT/decision.json" 2> "$OUT/decide.err"); drc=$?
else
  DEC="prerun_decide_x8.py is not the pinned file (sha256 $(sha_of "$DECIDE"), pin $DECIDE_PIN)"; drc=71
fi
printf '%s\n' "$DEC" > "$OUT/decide.out"
LAST=$(printf '%s\n' "$DEC" | tail -1)
stated() { [ "$LAST" = "DECISION path=$1 sha=$EXPECT branch=$BR" ] && /usr/bin/grep -qF "\"path\": \"$1\"" "$OUT/decision.json" 2>/dev/null && /usr/bin/grep -qF "\"sha\": \"$EXPECT\"" "$OUT/decision.json" 2>/dev/null && /usr/bin/grep -qF "\"branch\": \"$BR\"" "$OUT/decision.json" 2>/dev/null; }
PATHSEL=hook; WHY=""
if [ "$drc" -eq 0 ] && stated no-verify; then PATHSEL=noverify; say "PUSH PATH: --no-verify of $EXPECT, the pre-run record qualifies: $LAST"
elif [ "$drc" -eq 5 ] && stated refuse; then say "GATE FAIL: the pre-run record shows a FAILED pre-run; nothing pushed, leaving the queue: $(printf '%s\n' "$DEC" | tr '\n' ';' | cut -c1-700)"; exit 5
elif [ "$drc" -eq 10 ]; then WHY=$(printf '%s\n' "$DEC" | /usr/bin/grep '^DECISION-DETAIL' | cut -c1-200); say "PUSH PATH: FALL BACK to the hook under the lock, the place is kept: $(printf '%s\n' "$DEC" | tr '\n' ';' | cut -c1-700)"
else WHY="DECIDE ERROR rc=$drc, no positive decision"; say "DECIDE ERROR rc=$drc, no positive decision: falling back to the hook under the lock: $(printf '%s ' "$DEC" | head -c 300 | tr '\n' ' ') $(head -c 300 "$OUT/decide.err" 2>/dev/null | tr '\n' ' ')"; fi
echo "$PATHSEL" > "$OUT/push.path"
if [ "$PATHSEL" = hook ]; then
  # X7: the load gate, exactly as v3 (it moved here from before the precheck, because the path is only known now): the hook's preflight is about to start under this lock.
  n=0; L1=99
  while [ "$n" -lt 60 ]; do
    L1=$(uptime | sed -E 's/.*load averages?: *([0-9.]+).*/\1/')
    awk -v l="$L1" 'BEGIN{exit !(l<16)}' && break; n=$((n+1)); sleep 3
  done
  awk -v l="$L1" 'BEGIN{exit !(l<16)}' || { say "GATE FAIL: load1 $L1 not < 16"; exit 4; }
  say "gate ok: load1=$L1 (< 16)"
else
  # X7 (X 5th's design point 4, approved 06:15:29Z): no hook runs under this lock on the --no-verify path, so the load gate would protect nothing; it LOGS and neither waits nor exits.
  say "load1=$(uptime | sed -E 's/.*load averages?: *([0-9.]+).*/\1/') logged only: no hook runs under this lock on the --no-verify path"
fi
[ "$MODE" = gatetest ] && { say "gatetest: all gates passed, stopping BEFORE the push"; exit 0; }

# ---- 3. push: keepalives for THIS command only; rc in its own file; ls-remote in the same action -------------------------------
t0=$(date +%s); say "PUSH start path=$PATHSEL (head $(git -C "$WT" rev-parse HEAD))"
if [ "$PATHSEL" = noverify ]; then
  # X7: the explicit sha, --no-verify, under a hard bound (PUSH_BOUND). After a non-zero rc ORIGIN IS READ FIRST (X 5th's point 6): holds EXPECT = it landed (no retry); holds nothing = retry, at most
  # 2 times, RETRY_SLEEP apart; holds a DIFFERENT sha = refuse (exit 5); the read itself failing = exit 6 ("could not say"). The record is not consumed by a failed push: the sha has not changed.
  att=0
  while :; do
    gitnet_b "$PUSH_BOUND" push --no-verify origin "$EXPECT:refs/heads/$BR" > "$OUT/push.out" 2>&1; prc=$?
    echo "$prc" >> "$OUT/push.rc.all"
    [ "$prc" -eq 0 ] && break
    gitnet ls-remote origin "refs/heads/$BR" > "$OUT/lsr_after_push.out" 2> "$OUT/lsr_after_push.err"; lrc=$?
    if [ "$lrc" -ne 0 ]; then say "push rc=$prc and the ls-remote that reads origin failed rc=$lrc: could not say; nothing more is tried"; exit 6; fi
    osha=$(awk '{print $1}' "$OUT/lsr_after_push.out")
    if [ "$osha" = "$EXPECT" ]; then say "push rc=$prc but origin holds $EXPECT at $BR: it landed, no retry"; prc=0; break; fi
    if [ -n "$osha" ]; then say "push rc=$prc and origin holds a DIFFERENT sha $osha at $BR: refusing, nothing more is pushed"; exit 5; fi
    [ "$att" -lt 2 ] || { say "push rc=$prc, origin holds nothing, 2 retries used: giving up"; break; }
    att=$((att+1)); say "push rc=$prc, origin holds nothing: retry $att of 2 in ${RETRY_SLEEP} s"; sleep "$RETRY_SLEEP"
  done
  echo "$prc" > "$OUT/push.rc"
else
  # X7: the fallback is v3's push (the hook runs under the lock), now under a hard bound too (HOOKPUSH_BOUND); no retry, as v3.
  gitnet_b "$HOOKPUSH_BOUND" push origin "refs/heads/$BR:refs/heads/$BR" > "$OUT/push.out" 2>&1
  echo $? > "$OUT/push.rc"
fi
t1=$(date +%s); say "PUSH end rc=$(cat "$OUT/push.rc") elapsed=$((t1-t0))s"
gitnet ls-remote origin "refs/heads/$BR" > "$OUT/lsremote.txt" 2> "$OUT/lsremote.err"   # X7 (finding 8): the -v wrapper writes non-debug ssh lines to stderr; they must not reach awk
LSSHA=$(awk '{print $1}' "$OUT/lsremote.txt")
say "ls-remote: $(cat "$OUT/lsremote.txt")"
if [ "$(cat "$OUT/push.rc")" = "0" ] && [ "$LSSHA" = "$EXPECT" ]; then say "VERIFIED: origin $BR is $EXPECT"; else say "NOT VERIFIED: push rc=$(cat "$OUT/push.rc"), origin line=[$LSSHA]"; fi
# X7: the line the seat pastes into the PR says which path was taken (--no-verify and which checks ran, or that the hook ran).
# X7 (finding 11): written from the PUSH RESULT and the hook's own output, by a tool separate from decide, so a broken decide cannot write it. Anything else is a plain NO PR LINE.
if [ "$(sha_of "$PRLINE")" = "$PRLINE_PIN" ]; then
  PL=$(python3 -I "$BOUND" "$NET_BOUND" python3 -I "$PRLINE" --path "$PATHSEL" --push-rc "$(cat "$OUT/push.rc")" --origin-sha "$LSSHA" --sha "$EXPECT" --branch "$BR" --push-out "$OUT/push.out" --decision "$OUT/decision.json" --status "$ST" --why "$WHY" 2> "$OUT/prline.err"); plc=$?
else
  PL=""; plc=71
fi
if [ "$plc" -eq 0 ] && [ -n "$PL" ]; then printf '%s\n' "$PL" > "$OUT/pr_line.txt"; else say "the PR-line tool failed rc=$plc: $(head -c 200 "$OUT/prline.err" 2>/dev/null)"; printf 'NO PR LINE: the line tool failed (rc %s); the push result is in %s.\n' "$plc" "$ST" > "$OUT/pr_line.txt"; fi
# The driver's exit status is the PUSH's (a refused push must not read as success in a wrapper).
exit "$(cat "$OUT/push.rc")"
